block.dot:
digraph sample_capture_block {
    rankdir=LR;
    nodesep=0.5;
    ranksep=0.8;
    node [fontname="Helvetica", fontsize=12, shape=none, margin=0];
    edge [dir=none, penwidth=2.5, color="black"];

    // Generics box
    gen_box_sample_capture [label=<
        <TABLE BORDER="2" CELLBORDER="0" CELLSPACING="3" CELLPADDING="0" BGCOLOR="#c8f5c4" COLOR="#1a5c1a">
          <TR><TD PORT="g_STICKY_OVERFLOW" ALIGN="LEFT" CELLPADDING="5">STICKY_OVERFLOW = 1&#x27;b1</TD></TR>
        </TABLE>>];

    // Ports box
    port_box_sample_capture [label=<
        <TABLE BORDER="2" CELLBORDER="0" CELLSPACING="3" CELLPADDING="0" BGCOLOR="#fffde7" COLOR="#5d4200">
          <TR><TD PORT="i_clk" ALIGN="LEFT" CELLPADDING="5">&#x25B8; clk</TD><TD WIDTH="50"> </TD><TD PORT="o_sample_data" ALIGN="RIGHT" CELLPADDING="5">sample_data &#x25C2;</TD></TR>
          <TR><TD PORT="i_rst_n" ALIGN="LEFT" CELLPADDING="5">&#x25B8; rst_n</TD><TD WIDTH="50"> </TD><TD PORT="o_sample_valid" ALIGN="RIGHT" CELLPADDING="5">sample_valid &#x25C2;</TD></TR>
          <TR><TD PORT="i_enable" ALIGN="LEFT" CELLPADDING="5">&#x25B8; enable</TD><TD WIDTH="50"> </TD><TD PORT="o_overflow" ALIGN="RIGHT" CELLPADDING="5">overflow &#x25C2;</TD></TR>
          <TR><TD PORT="i_clear_overflow" ALIGN="LEFT" CELLPADDING="5">&#x25B8; clear_overflow</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
          <TR><TD PORT="i_adc_clk" ALIGN="LEFT" CELLPADDING="5">&#x25B8; adc_clk</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
          <TR><TD PORT="i_adc_rst" ALIGN="LEFT" CELLPADDING="5">&#x25B8; adc_rst</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
          <TR><TD PORT="i_adc_data" ALIGN="LEFT" CELLPADDING="5">&#x25B8; adc_data [full_pkg::SAMPLE_W-1:0]</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
          <TR><TD PORT="i_sample_ready" ALIGN="LEFT" CELLPADDING="5">&#x25B8; sample_ready</TD><TD WIDTH="50"> </TD><TD CELLPADDING="5"> </TD></TR>
        </TABLE>>];

    { rank=same; gen_box_sample_capture; port_box_sample_capture }
    gen_box_sample_capture -> port_box_sample_capture [style=invis, weight=100];

}
